// L01-Parse: a message is feedback inbound only if it was addressed to the plus-address pc7900+wf<N>@... (our Reply-To).
// Our own outbound mail goes to the user, so it never matches. Quoted history is cut so the thread shows only the new text.
const m = $input.first().json;
const addrs = [m.to && m.to.text, m.cc && m.cc.text, m.headers && m.headers['delivered-to'], m.headers && m.headers.to].filter(Boolean).join(' , ');
const hit = /\+wf(\d+)@/i.exec(addrs);
const fromAddr = ((m.from && m.from.value && m.from.value[0] && m.from.value[0].address) || '').toLowerCase();
let text = String(m.text || '').replace(/\r\n/g, '\n');
if (!text && m.html) text = String(m.html).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '');
const cuts = [
  text.search(/^On .{0,200}?wrote:\s*$/ms),
  text.search(/^>/m),
  text.search(/^-{2,}\s*(Original Message|Forwarded message)/mi),
  text.search(/^--\s*\nIn reply to your feedback:/m)
].filter((i) => i >= 0);
const body = (cuts.length ? text.slice(0, Math.min(...cuts)) : text).trim();
return [{ json: {
  matched: !!hit && body.length > 0,
  feedback_id: hit ? parseInt(hit[1], 10) : null,
  from_email: fromAddr,
  to_text: String(m.to && m.to.text || ''),
  subject: String(m.subject || ''),
  body: body || text.trim(),
  message_id: String(m.messageId || ''),
  received_at: m.date ? new Date(m.date).toISOString() : new Date().toISOString()
} }];
